	bounds := make([]float64, 0, 31)
	for b := 10; b <= 40; b++ {
		bounds = append(bounds, float64(uint64(1)<<b))
	}
	return bounds
}()

// initMetrics registers the repack instruments against the global meter
// provider. One-shot: a registration error leaves the instrument nil and
// recordDiskBytes no-ops for the life of the process, so the WARN here is
// the only signal.
func (s *repackScanner) initMetrics(ctx context.Context) {
	s.metricsOnce.Do(func() {
		meter := otel.Meter("entire.io/diss")
		var err error
		if s.diskBytesHist, err = meter.Int64Histogram(
			"diss.repo.disk_bytes",
			metric.WithDescription("Per-repo object bytes on this node (pack files plus loose objects, excluding .idx/.rev), one sample per local replica per repack pass. Tagged by size_class; filter out uninitiated to drop empty shells. Percentiles give the fleet repo-size distribution for capacity and cost projection."),
			metric.WithUnit("By"),
			metric.WithExplicitBucketBoundaries(diskBytesBucketBounds...),
		); err != nil {
			slogutil.Warn(ctx, "repack: register disk_bytes histogram failed", slog.Any("error", err))
		}
	})
}

// recordDiskBytes records one histogram sample per repo from the stats the
// pass already collected. It adds no I/O: PackBytes and LooseBytes come from
// CollectRepoStats.
func (s *repackScanner) recordDiskBytes(ctx context.Context, repos []objstore.RepoStats) {
	if s.diskBytesHist == nil {
		return
	}
	for _, rs := range repos {
		s.diskBytesHist.Record(ctx, rs.PackBytes+rs.LooseBytes,
			metric.WithAttributes(attribute.String("size_class", rs.SizeClass().String())))
	}
}

// runRepack is invoked by the shared taskloop, which handles scheduling,
// jitter, and tracing; this function only does one pass across local repos.
func (s *repackScanner) runRepack(ctx context.Context) error {
	ctx, span := entireotel.Tracer().Start(ctx, "diss.repack.pass")
	defer span.End()

	s.initMetrics(ctx)
	slogutil.Info(ctx, "repack: starting pass")

	startTime := time.Now()
	repos, err := s.localStorage.CollectRepoStats(ctx)
	if err != nil {
		span.RecordError(err)
		span.SetStatus(otelcodes.Error, "failed to collect repo stats")
		return fmt.Errorf("collect repo stats: %w", err)
	}

	slogutil.Info(ctx, "repack: collected repo stats",
		slog.Int("total_repos", len(repos)),
		slog.String("stats_duration", time.Since(startTime).String()))
	s.recordDiskBytes(ctx, repos)

	// Classify repos from the stats just collected (part 1: observation only —
	// the tags do not yet influence the ordering below). Best-effort: a failure
	// only leaves classification stale, it must not stop the repack pass.
	if sum, cerr := s.localStorage.ClassifyStaleRepos(ctx, repos, time.Now()); cerr != nil {
		slogutil.Warn(ctx, "repack: classification failed", slog.Any("error", cerr))
	} else {
		slogutil.Info(ctx, "repack: classified repos",
			slog.Int("classified", sum.Classified),
			slog.Int("skipped", sum.Skipped))
	}

