	tips     bitmapfile.Tips
	discover TipDiscoverer
	read     bool
}

func (pt *passTips) full(ctx context.Context) bitmapfile.Tips {
	if pt.discover != nil && !pt.read {
		pt.read = true
		pt.tips.Discovered = append(pt.tips.Discovered, pt.discover(ctx)...)
	}
	return pt.tips
}

// hasTips reports whether the pass has any tip to encode from. Required tips
// answer without a ref read.
func (pt *passTips) hasTips(ctx context.Context) bool {
	return len(pt.tips.Required) > 0 || pt.full(ctx).Len() > 0
}

// RunMaintenance performs the requested level of maintenance for a single
// repository, coordinating the operations in the correct order to avoid
// race conditions. See [MaintenanceLevel] for the available levels. tips
// selects the bitmap entries: Required tips must resolve in the packs,
// Discovered ones are dropped when they do not (bitmapfile.Tips).
//
// RunMaintenance does not wait for the repo's maintenance lock. It returns
// ErrMaintenanceBusy when another run or a purge holds it, ErrStorageClosing
// once Close has begun, and an error that wraps ErrRepoNotTracked when the
// repo is not tracked.
func (o *LocalStorage) RunMaintenance(ctx context.Context, repoID repositories.ID, level MaintenanceLevel, tips bitmapfile.Tips, opts ...MaintenanceOption) error {
	ctx, span := otel.Tracer().Start(ctx, "objstore.LocalStorage.RunMaintenance")
	defer span.End()
	span.SetAttributes(
		attribute.String("repo_id", repoID.String()),
		attribute.String("maintenance.level", level.String()),
		attribute.Int("tips", tips.Len()),
	)
	pt := &passTips{tips: tips}
	for _, opt := range opts {
		opt(pt)
	}
	defer func() {
		span.SetAttributes(
			attribute.Bool("tips.refs_read", pt.read),
			attribute.Int("tips.discovered", len(pt.tips.Discovered)),
		)
	}()

	pm := o.PackfileManager()
	if pm == nil {
		return nil
	}

	rm := o.acquireMaint(repoID)
	defer o.releaseMaint(repoID, rm)
	if !rm.tryLock() {
		span.SetAttributes(attribute.Bool("maintenance.busy", true))
		return ErrMaintenanceBusy
	}

	// Close barrier (ENT-966): register with maintWG so Close waits for this
	// run before munmapping the packfile indexes. Add under closeMu while
	// closing is false so the Add can never race Close's Wait. If we're
	// already closing, touch no mmap and bail.
	o.closeMu.Lock()
	if o.closing {
		o.closeMu.Unlock()
		rm.unlock()
		return ErrStorageClosing
	}
	o.maintWG.Add(1)
	o.closeMu.Unlock()
	defer o.maintWG.Done()

	// Derive a context that also cancels when the store closes, so this run
	// bails at its next ctx check regardless of which path drove it. Fast-fail
	// if shutdown already began, before any mmap I/O (RemoveStaleMidxBitmaps /
	// ListSets / PackLooseObjects all touch the manager's mappings) (ENT-966).
	// PurgeRepo cancels it too.
	ctx, cancel := o.maintCtx(ctx)
	lockedAt := rm.beginRun(cancel)
	defer func() {
		rm.endRun()
		// After endRun: the assertion waits for a purge that waits for the lock.
		o.assertNoWriteBackAfterPurge(context.WithoutCancel(ctx), repoID, lockedAt)
	}()
	defer cancel()
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("maintenance cancelled: %w", err)
	}

	// A purge untracks the repo before it releases the lock. A run that takes
	// the lock after the purge must not write the repo back (ENT-2867).
	if !o.IsRepoTracked(repoID) {
		span.SetAttributes(attribute.Bool("maintenance.untracked", true))
		return fmt.Errorf("maintenance: %w", ErrRepoNotTracked)
	}

	// Timing starts here rather than at entry so lock-busy and closing
	// returns — which do no work — stay out of the totals.
	runStart := time.Now()
	defer func() {
		// WithoutCancel: a run cut short by store shutdown still consumed the
		// time, and dropping exactly those runs would bias the totals toward
		// whichever level happens to survive a deploy.
		recordMaintenanceRun(context.WithoutCancel(ctx), level, time.Since(runStart))
	}()

	slogutil.Info(ctx, "maintenance: starting",
		slog.String("repo_id", repoID.String()),
		slog.String("maintenance_level", level.String()),
		slog.Int("tips", tips.Len()))

	// Step 0: snapshot initial state and clean up stale bitmaps left by
	// the previous run (including partial writes from a crash mid-encode).
	// By now any reader using the old MIDX is long gone.
	pm.RemoveStaleMidxBitmaps(ctx, repoID)
	startingSets, err := pm.ListSets(repoID)
	if err != nil {
		return fmt.Errorf("existing packfiles: %w", err)
	}

	// Step 1: Pack loose objects — required at all levels because refs
	// may point to loose objects and the bitmap encoder needs every
	// referenced object in a packfile. view is the resulting authoritative
	// pack list: every pack a fresh index must reference. From here on each
	// stage transforms the view, and step 4 deletes only what fell out of
	// it — so a pack the just-written index references is never deletable.
	view, err := o.PackLooseObjects(ctx, repoID, startingSets)
	if err != nil {
		return fmt.Errorf("pack loose objects: %w", err)
	}

	// GeometricRepack has its own flow (chainMaintain: roll up only the packs
	// chain state makes candidates, then fold the tip by the merge
	// condition). It returns before the generic append-vs-collapse logic
	// below.
	if level == GeometricRepack {
		if err := o.chainMaintain(ctx, repoID, view, pt, true); err != nil {
			return err
		}
		// Incremental MIDX path: append the graph in lockstep (O(new)),
		// bootstrapping flat if there is no chain base yet. The flat rebuilds
		// already refreshed it pre-encode, so this is a covered no-op there;
		// the chain commits, a layer-mode encode the graph never accelerates,
		// rely on this call.
		o.appendCommitGraphBestEffort(ctx, repoID, pt.tips.All(), true)
		return nil
	}

	// CollapseMidx compacts the chain suffix by the layer merge condition
	// instead of flattening it — chains are the steady state, and the depth>1
	// flatten would undo the strategy hourly. The flatten below remains the
	// backstop at the hard depth cap (where the merge fixpoint has clearly
	// failed to bound depth) and for shallow chains (depth <= 1 has nothing
	// to compact; the generic path handles commit-graph-only dirt).
	if level == CollapseMidx {
		if depth := pm.MidxChainDepth(repoID); depth > 1 && depth < maxChainDepth {
			if err := o.chainMaintain(ctx, repoID, view, pt, false); err != nil {
				return err
			}
			// Chain-suffix compaction is incremental: append the graph in
			// lockstep (O(new)), bootstrapping flat if there is no base yet.
			o.appendCommitGraphBestEffort(ctx, repoID, pt.tips.All(), true)
			return nil
		}
	}

	// Decide append vs collapse. RefreshMidx appends a layer onto the
	// existing chain (cheap); CollapseMidx and FullRepack flatten it back to
	// a single MIDX. A RefreshMidx also collapses when there's no base to
	// append onto, the chain has hit the depth cap, or there are no tips for
	// a layer bitmap: an immutable bitmap-less chain layer would never
	// self-heal, whereas a flat MIDX is rewritten (with a bitmap) next run.
	collapse := level >= CollapseMidx
	if !collapse {
		depth := pm.MidxChainDepth(repoID)
		span.SetAttributes(attribute.Int("midx.depth", depth))
		if depth == 0 || depth >= maxChainDepth || !pt.hasTips(ctx) {
			collapse = true
		}
	}

	if !collapse {
		// RefreshMidx: append the packs not yet covered by the chain as a
		// new layer. No full rewrite, no pack consolidation. AppendMidxLayer
		// filters covered packs itself against the chain it loads anyway, so
		// the push path opens the MIDX once (ENT-813).
		n, err := pm.AppendMidxLayer(ctx, repoID, view, pt.tips)
		switch {
		case err == nil && n == 0:
			slogutil.Info(ctx, "maintenance: midx already current, nothing to append",
				slog.String("repo_id", repoID.String()))
			// The graph chain is independent of the MIDX chain, so a torn prior
			// append can leave it behind even when the MIDX is current — the
			// covered-tips check makes this a cheap no-op in the common case.
			o.appendCommitGraphBestEffort(ctx, repoID, pt.tips.All(), false)
			return nil
		case err == nil:
			slogutil.Info(ctx, "maintenance: appended midx layer",
				slog.String("repo_id", repoID.String()),
				slog.Int("objects", n))
			// The per-push win: append the graph's new commits (O(new))
			// instead of re-encoding all of history. No flat bootstrap here —
			// a structural pass builds the first flat graph.
			o.appendCommitGraphBestEffort(ctx, repoID, pt.tips.All(), false)
			return nil
		case errors.Is(err, packfile.ErrNoBaseForAppend):
			// Raced with chain removal; fall through to the flat build below.
		case errors.Is(err, packfile.ErrAppendClosureIncomplete):
			// Replica refs ahead of objects (ENT-1071): the layer bitmap can't
			// close over a not-yet-replicated object. Fall through to the flat
			// build — it installs the MIDX bitmap-less (ENT-1022) so packs still
			// consolidate, and it self-heals once the objects replicate. A
			// bitmap-less chain layer is immutable and would never self-heal.
			slogutil.Warn(ctx, "maintenance: layer bitmap closure incomplete (refs ahead of objects); flat-rebuilding without bitmap",
				slog.String("repo_id", repoID.String()),
				slog.Any("error", err))
		default:
			return fmt.Errorf("append midx layer: %w", err)
		}
	}

	// Step 2: Consolidate packfiles (FullRepack only) — view in, view out.
	// The new pack is written but old packs are kept alive until after the
	// MIDX is written; when there is nothing to consolidate the view passes
	// through unchanged.
	packs := view
	if level >= FullRepack {
		packs, err = o.consolidateWriteOnly(ctx, repoID, view, pt.tips.All())
		if err != nil {
			return fmt.Errorf("consolidate packfiles: %w", err)
		}
	}

	if repackAbortTestHook != nil {
		if err := repackAbortTestHook("pack-written"); err != nil {
			return err
		}
	}

	// Step 3: Write the MIDX + bitmap over the post-consolidation view. The
	// commit-graph is refreshed against the staged MIDX first so the bitmap
	// encode can walk the graph instead of decoding commit headers (ENT-2033);
	// only structural levels bootstrap a graph that doesn't exist yet — a
	// RefreshMidx that fell through to the flat build catches up an existing
	// graph but never takes on the first O(history) build.
	slogutil.Info(ctx, "maintenance: writing MIDX and bitmap",
		slog.String("repo_id", repoID.String()),
		slog.Int("packs", len(packs)))

	graphMode := packfile.CommitGraphCatchUp
	if level >= CollapseMidx {
		graphMode = packfile.CommitGraphBootstrap
	}
	flatTips := pt.full(ctx)
	logBitmapEncodeTips(ctx, repoID, flatTips)
	if _, err = pm.WriteMidxAndBitmapForSets(ctx, repoID, packs, flatTips.Required,
		packfile.WithDiscoveredTips(flatTips.Discovered),
		packfile.WithCommitGraphRefresh(graphMode)); err != nil {
		return fmt.Errorf("write midx: %w", err)
	}

	if repackAbortTestHook != nil {
		if err := repackAbortTestHook("midx-written"); err != nil {
			return err
		}
	}

	// Collapse any existing chain: the flat multi-pack-index is now live,
	// so drop the chain manifest + layer dir. This must succeed before old
	// packs are deleted, since a surviving chain still references them.
	if err := pm.RemoveChain(repoID); err != nil {
		return fmt.Errorf("collapse chain: %w", err)
	}

	// Step 4: Delete the packs that fell out of the view — everything the
	// pre-consolidation view held that the just-written MIDX does not
	// reference. Deriving the set by subtraction (rather than deleting a
	// stage's inputs wholesale) is what makes "delete the pack the fresh
	// MIDX references" unrepresentable: the reused-input consolidation
	// outcome is in packs, so it can never be in the difference. In-flight
	// readers that already opened an old .pack via fd continue (Unix
	// unlink semantics).
	if consolidationMidTestHook != nil {
		consolidationMidTestHook()
		consolidationMidTestHook = nil
	}
	if stale := subtractSetsByIdxName(view, packs); len(stale) > 0 {
		slogutil.Info(ctx, "maintenance: deleting old packs",
			slog.String("repo_id", repoID.String()),
			slog.Int("old_packs", len(stale)))
		deletePackSets(ctx, stale)
	}

	if repackAbortTestHook != nil {
		if err := repackAbortTestHook("packs-deleted"); err != nil {
			return err
		}
	}

	slogutil.Info(ctx, "maintenance: complete",
		slog.String("repo_id", repoID.String()))

	// CollapseMidx and FullRepack refreshed the commit-graph against the
	// staged MIDX before the bitmap encode (step 3), so this is normally a
	// covered no-op; it remains as the backstop when that best-effort refresh
	// failed. RefreshMidx is excluded even when it fell through to a flat
	// build (ErrNoBaseForAppend / closure-incomplete): it is a
	// per-push/recovery path, not a structural repack, so it does not take
	// on the O(commits) commit-graph rebuild here either.
	if level >= CollapseMidx {
		o.writeCommitGraphBestEffort(ctx, repoID, flatTips.All())
	}

	return nil
}

// appendCommitGraphBestEffort appends a commit-graph layer for the push tips —
// the O(new commits) counterpart to writeCommitGraphBestEffort's full rebuild,
// used by the incremental MIDX paths so the graph folds in lockstep with the
// MIDX chain. When there is no chain base yet or the depth backstop fired
// (ErrNoCommitGraphBase), it rebuilds flat iff bootstrapFlat; otherwise it skips
// and leaves the graph for a later structural pass — the per-push path must never
// take on the O(history) flat rebuild. Best-effort: failures are logged and
// never fail maintenance, and the append leaves any existing graph intact on
// error (incomplete closure, no MIDX) by design.

content.content:
			return nil, fmt.Errorf("read object count %s: %w", s.PackPath, err)
		}
		counts[i] = c
	}
	return counts, nil
}

