func (o *LocalStorage) consolidateWriteOnly(ctx context.Context, repoID repositories.ID, inputSets []packfile.Set, tipHashes []plumbing.Hash, opts ...packfile.RepackOption) ([]packfile.Set, error) {
	ctx, span := otel.Tracer().Start(ctx, "objstore.LocalStorage.consolidateWriteOnly")
	defer span.End()

	pm := o.PackfileManager()
	if pm == nil {
		return nil, errors.New("no packfile manager (in-memory storage)")
	}

	if len(inputSets) < 2 {
		return inputSets, nil
	}

	idxNames := make([]string, len(inputSets))
	for i, s := range inputSets {
		idxNames[i] = s.IdxName()
	}
	packs, err := pm.AllocPacksByName(repoID, idxNames)
	if err != nil {
		return nil, fmt.Errorf("load packfiles: %w", err)
	}
	defer func() {
		for _, lp := range packs {
			_ = lp.Close()
		}
	}()

	span.SetAttributes(
		attribute.String("repo_id", repoID.String()),
		attribute.Int("packfiles", len(packs)),
	)

	if len(packs) < 2 {
		return inputSets, nil
	}

	seen := make(map[plumbing.Hash]struct{})
	var allHashes []plumbing.Hash
	zeroEntries := 0
	inputEntries := 0
	for _, lp := range packs {
		entries, err := lp.AllEntries()
		if err != nil {
			return nil, fmt.Errorf("all entries: %w", err)
		}
		for _, e := range entries {
			// A zero-hash entry is a corrupt-index artifact: the index was
			// finalized with the entry unresolved, so nothing can name the
			// object. Drop it — carrying it forward would trip WriteIndex's
			// zero-hash rejection and wedge maintenance on this repo.
			if e.Hash.IsZero() {
				zeroEntries++
				continue
			}
			inputEntries++
			if _, dup := seen[e.Hash]; !dup {
				seen[e.Hash] = struct{}{}
				allHashes = append(allHashes, e.Hash)
			}
		}
	}
	if zeroEntries > 0 {
		span.SetAttributes(attribute.Int("zero_hash_entries_dropped", zeroEntries))
		slogutil.Warn(ctx, "consolidation dropping zero-hash entries from corrupt source index",
			slog.String("repo_id", repoID.String()),
			slog.Int("entries", zeroEntries))
	}

	var filteredTipHashes []plumbing.Hash
	for _, tip := range tipHashes {
		if _, dup := seen[tip]; dup {
			filteredTipHashes = append(filteredTipHashes, tip)
		}
	}

	totalObjects := len(allHashes)
	// dup_entries is the cross-input duplication this rewrite collapses (a
	// mirror-style push stream re-sending objects an input pack already
	// holds). Its byte-side complement is input_bytes vs output_bytes below.
	span.SetAttributes(
		attribute.Int("objects", totalObjects),
		attribute.Int("consolidate.input_entries", inputEntries),
		attribute.Int("consolidate.dup_entries", inputEntries-totalObjects),
	)

	if totalObjects == 0 {
		return inputSets, nil
	}

	hashSet := make(map[plumbing.Hash]struct{}, totalObjects)
	for _, h := range allHashes {
		hashSet[h] = struct{}{}
	}
	// External entries are copied as they are. A repack never fetches the
	// body of an offloaded blob.
	externals, err := packfile.TakeExternalEntries(packs, hashSet)
	if err != nil {
		return nil, fmt.Errorf("take external entries: %w", err)
	}
	if len(externals) > 0 {
		opts = append(opts, packfile.WithExternalEntries(externals))
	}
	runsOpt, runObjects, runDeltaDepths, err := packfile.FindAndAttachRuns(ctx, packs, hashSet, 4)
	if err != nil {
		return nil, fmt.Errorf("find reusable runs: %w", err)
	}
	opts = append(opts, runsOpt, packfile.WithWindowBytes(repackWindowBytes))

	remainingHashes := make([]plumbing.Hash, 0, len(hashSet))
	for h := range hashSet {
		remainingHashes = append(remainingHashes, h)
	}

	// Reuse existing OFS_DELTAs verbatim rather than resolving and
	// re-delta-compressing them. Every delta's base is an entry in these same
	// source packs — a run object, a resolved object, or another reused delta —
	// so all bases land in the output pack. The rest go through the resolve +
	// recompute path below.
	candidateDeltas, err := pm.GetBatchRawDeltas(packs, remainingHashes)
	if err != nil {
		return nil, fmt.Errorf("read reusable deltas: %w", err)
	}
	// Drop deltas that would form a cycle (the same object stored with opposite
	// delta directions across packs), then deltas whose reuse would land deeper
	// than the writer's chain cap (ENT-2347); both kinds fall into
	// resolveHashes below since they are no longer in reusableDeltas.
	reusableDeltas, _ := packfile.PlanReusableDeltas(candidateDeltas)
	rootDepths := runDeltaDepths.DepthsFor(packfile.ReuseChainRoots(reusableDeltas))
	reusableDeltas, depthDemoted := packfile.BoundReusableDeltaDepth(reusableDeltas, rootDepths)
	opts = append(opts, packfile.WithReusableDeltas(reusableDeltas))

	resolveHashes := make([]plumbing.Hash, 0, len(remainingHashes)-len(reusableDeltas))
	for _, h := range remainingHashes {
		if _, reused := reusableDeltas[h]; !reused {
			resolveHashes = append(resolveHashes, h)
		}
	}

	span.SetAttributes(
		attribute.Int("run_objects", runObjects),
		attribute.Int("remaining_objects", len(remainingHashes)),
		attribute.Int("reused_deltas", len(reusableDeltas)),
		attribute.Int("consolidate.depth_demoted", len(depthDemoted)),
		attribute.Int("resolved_objects", len(resolveHashes)),
	)

	slogutil.Info(ctx, "consolidating packfiles",
		slog.String("repo_id", repoID.String()),
		slog.Int("packfiles", len(packs)),
		slog.Int("total_objects", totalObjects),
		slog.Int("run_objects", runObjects),
		slog.Int("remaining_objects", len(remainingHashes)),
		slog.Int("reused_deltas", len(reusableDeltas)),
		slog.Int("depth_demoted", len(depthDemoted)),
		slog.Int("resolved_objects", len(resolveHashes)))

	resolved, missing, err := packfile.GetBatchResolved(ctx, packs, resolveHashes, packfile.NewDeltaBaseCache())
	if err != nil {
		return nil, fmt.Errorf("resolve objects: %w", err)
	}
	if len(missing) > 0 {
		return nil, fmt.Errorf("missing %d objects during consolidation", len(missing))
	}

	objects := make([]packfile.RepackObject, 0, len(resolved))
	for hash, obj := range resolved {
		objects = append(objects, packfile.RepackObject{
			Hash:    hash,
			Type:    obj.Type,
			Content: obj.Content,
		})
	}

	format := resolveRepoObjectFormat(ctx, o, repoID)
	annotateObjectNames(ctx, objects, hashSizeForFormat(format))

	newSet, _, err := o.writeAndStorePackfile(ctx, pm, repoID, objects, filteredTipHashes, opts...)
	if err != nil {
		return nil, err
	}

	// input vs output bytes = what this rewrite reclaimed (dedup + delta
	// recompression). Read together with midx.chain.tip.retained_dup_entries:
	// duplication against packs *not* in this rollup is deliberately retained
	// (ADR 20260617 amendment) and shows up there instead.
	span.SetAttributes(
		attribute.Int64("consolidate.input_bytes", packSetsBytes(inputSets)),
		attribute.Int64("consolidate.output_bytes", packSetsBytes([]packfile.Set{newSet})),
	)

	return []packfile.Set{newSet}, nil
}

// packSetsBytes sums the on-disk .pack sizes of sets. Telemetry-only: a pack
// that fails to stat contributes 0 rather than failing the pass.
func packSetsBytes(sets []packfile.Set) int64 {
	var total int64
	for _, s := range sets {
		if fi, err := os.Stat(s.PackPath); err == nil {
			total += fi.Size()
		}
	}
	return total
}

// deletePackSetsTestHook, if set, runs once inside deletePackSets after the
// live-keep re-check and before the .idx/.pack removals. Test-only (nil in
// production): it lets a test drive a reader across the deletion window to
// prove an already-loaded snapshot survives pack unlink.
//
// Locality: this seam only exercises the invariant at this call site; a new
// pack-deletion path added elsewhere bypasses it and is not covered by the
// associated test.
var deletePackSetsTestHook func()

// deletePackSets removes the given pack sets from disk. Indexes and reverse
// indexes are deleted first — once the .idx is gone, no new reader will open
// the old .pack. In-flight readers that already opened via fd continue
// reading (Unix unlink semantics).
func deletePackSets(ctx context.Context, sets []packfile.Set) {
	_, span := otel.Tracer().Start(ctx, "objstore.deletePackSets")
	defer span.End()
	span.SetAttributes(attribute.Int("sets", len(sets)))

	// Skip any set whose hash has a live commit keep: a concurrent committer is
	// relying on canonical pack-<hash> being present so its Promote resolves as
	// "source gone, dest present => success" (ENT-1073). Deleting it out from
	// under that commit is exactly the promote-vs-repack race the keep prevents.
	// A keep-check error is treated conservatively as "keep present" — never
	// delete a pack we can't prove is unpinned.
	//
	// The keep is re-checked immediately before THIS set's removal, not in a
	// separate up-front scan: a scan-then-delete-all shape lets a keep written in
	// the gap between the scan and a later set's delete go unseen. Per-set,
	// check-adjacent-to-remove narrows the residual window to a single set's
	// check→remove — and that residual, if ever hit, is a retriable error (the
	// objects are durable in the consolidated pack), never data loss.
	var skipped, deleted int
	for _, set := range sets {
		live, err := packfile.HasLiveKeepForSet(set)
		if err != nil {
			skipped++
			slogutil.Warn(ctx, "skip pack deletion: keep check failed",
				slog.String("path", set.PackPath),
				slog.Any("error", err))
			continue
		}
		if live {
			skipped++
			slogutil.Info(ctx, "skip pack deletion: live commit keep",
				slog.String("path", set.PackPath))
			continue
		}
		deleted++

		if deletePackSetsTestHook != nil {
			deletePackSetsTestHook()
			deletePackSetsTestHook = nil
		}

		// .idx first (once it is gone no new reader opens the .pack), then .rev,
		// .bundle, and the per-pack .bitmap, then the .pack last. In-flight
		// readers holding an fd continue (Unix unlink semantics).
		if err := os.Remove(set.IdxPath); err != nil && !os.IsNotExist(err) {
			slogutil.Warn(ctx, "failed to remove old idx",
				slog.String("path", set.IdxPath),
				slog.Any("error", err))
		}
		if set.RevPath != "" {
			if err := os.Remove(set.RevPath); err != nil && !os.IsNotExist(err) {
				slogutil.Warn(ctx, "failed to remove old rev",
					slog.String("path", set.RevPath),
					slog.Any("error", err))
			}
		}
		if set.BundlePath != "" {
			if err := os.Remove(set.BundlePath); err != nil && !os.IsNotExist(err) {
				slogutil.Warn(ctx, "failed to remove old bundle",
					slog.String("path", set.BundlePath),
					slog.Any("error", err))
			}
		}
		if set.BitmapPath != "" {
			if err := os.Remove(set.BitmapPath); err != nil && !os.IsNotExist(err) {
				slogutil.Warn(ctx, "failed to remove old bitmap",
					slog.String("path", set.BitmapPath),
					slog.Any("error", err))
			}
		}
		if err := os.Remove(set.PackPath); err != nil && !os.IsNotExist(err) {
			slogutil.Warn(ctx, "failed to remove old pack",
				slog.String("path", set.PackPath),
				slog.Any("error", err))
		}
	}
	span.SetAttributes(
		attribute.Int("skipped_kept", skipped),
		attribute.Int("deleted", deleted),
	)

	if len(sets) > 0 {
		if err := fsdurable.SyncDir(filepath.Dir(sets[0].PackPath)); err != nil {
			slogutil.Warn(ctx, "failed to sync pack dir after deletion",
				slog.Any("error", err))
		}
	}
}

