func (o *LocalStorage) writeAndStorePackfile(ctx context.Context, pm *packfile.Manager, repoID repositories.ID, objects []packfile.RepackObject, tips []plumbing.Hash, opts ...packfile.RepackOption) (packfile.Set, bool, error) {
	ctx, span := otel.Tracer().Start(ctx, "objstore.LocalStorage.writeAndStorePackfile")
	defer span.End()

	format := resolveRepoObjectFormat(ctx, o, repoID)

	var empty packfile.Set

	span.SetAttributes(
		attribute.String("repo_id", repoID.String()),
		attribute.Int("objects", len(objects)),
		attribute.Int("tips.count", len(tips)),
		attribute.String("object_format", format.String()),
	)

	tmpFile, err := pm.CreateTempPackFile(repoID)
	if err != nil {
		return empty, false, fmt.Errorf("create temp packfile: %w", err)
	}
	tmpPath := tmpFile.Name()
	defer os.Remove(tmpPath) // no-op after successful rename

	idxEntries, err := packfile.WriteRepackPackfile(ctx, tmpFile, objects, format, opts...)
	if err != nil {
		_ = tmpFile.Close()
		return empty, false, fmt.Errorf("write packfile: %w", err)
	}
	var packSize int64
	packSizeKnown := false
	if packInfo, statErr := tmpFile.Stat(); statErr == nil {
		packSize = packInfo.Size()
		packSizeKnown = true
	}
	if err := tmpFile.Close(); err != nil {
		return empty, false, fmt.Errorf("close temp packfile: %w", err)
	}

	packHash, err := pm.TempPackHash(tmpPath, format)
	if err != nil {
		return empty, false, fmt.Errorf("read temp pack hash: %w", err)
	}

	// Pack names are content hashes, so a complete pack already on disk with
	// this hash holds these objects byte-for-byte. Skip the redundant
	// promote/index and report it as pre-existing. This is the common case
	// when maintenance re-runs within the loose-object TTL window and
	// re-packs the still-present (already-packed) loose objects into an
	// identical pack — indexing it again would hand the MIDX encoder a
	// duplicate pack name. Keying on FindPack (which requires the .idx
	// readiness marker) means a half-written pack from a concurrent ingestion
	// does not trigger the skip.
	if existing, ferr := pm.FindPack(repoID, packHash); ferr == nil {
		span.SetAttributes(attribute.Bool("pack.already_present", true))
		// The reused pack may carry no bundle (written by a path that
		// skipped it) or one advertising refs from its original creation,
		// and the caller goes on to delete every other pack's bundle.
		// Refresh it so bundle-uri offload keeps a current snapshot.
		o.writeRepackBundle(ctx, pm, repoID, packHash)
		return existing, false, nil
	}

	dir := pm.PackDir(repoID)
	root, err := os.OpenRoot(dir)
	if err != nil {
		return empty, false, fmt.Errorf("open pack root: %w", err)
	}
	defer root.Close()

	// Hold a keep for packHash across the whole install (index temps + the
	// pack→rev→idx renames). The orphan sweep reclaims keepless bare packs and
	// hash-named index temps promptly, so without a keep it could race this
	// live install and delete the pack after we return its Set — dropping a
	// pack the caller treats as durable and then deletes the old packs against
	// (ENT-1073). The hash is known up front here, so the keep also covers the
	// index write. Removed once the .idx readiness marker is in place.
	releaseKeep, keepErr := packfile.AcquireKeep(dir, packHash)
	if keepErr != nil {
		return empty, false, fmt.Errorf("write install keep: %w", keepErr)
	}
	defer releaseKeep()

	// Index the still-temp pack, writing suffixed .idx-tmp/.rev-tmp, then
	// install via InstallIndexedSet (.idx last, the readiness marker), so an
	// incomplete install never exposes a bare pack-<hash>.pack to
	// AllocPackfiles/ListSets or repack. The suffix isolates this attempt from
	// a concurrent identical repack of the same content.
	suffix := gitpack.NewTempSuffix()
	if err := gitpack.WriteIndex(root, idxEntries, packHash, format, gitpack.WithoutIndexFinalize(), gitpack.WithTempSuffix(suffix)); err != nil {
		packfile.RemoveIndexTemps(dir, packHash, suffix)
		return empty, false, fmt.Errorf("write index: %w", err)
	}
	packPath, err := pm.InstallIndexedSet(repoID, tmpPath, packHash, suffix)
	if err != nil {
		return empty, false, err //nolint:wrapcheck // InstallIndexedSet names the failing step
	}

	// Verify the installed set (canonical pack-<hash>, hash keyed off the
	// filename). Kept after the renames because VerifyHashesInPackfile resolves
	// the pack by its canonical name; a failure here signals real corruption and
	// leaves the set in place (a live set with its .idx), exactly as before.
	expectedHashes := make([]plumbing.Hash, len(idxEntries))
	for i := range idxEntries {
		expectedHashes[i] = idxEntries[i].Hash
	}
	if err := packfile.VerifyHashesInPackfile(packPath, expectedHashes); err != nil {
		return empty, false, fmt.Errorf("verification failed: %w", err)
	}

	span.SetAttributes(attribute.String("pack.hash", packHash.String()))
	if packSizeKnown {
		span.SetAttributes(attribute.Int64("pack.size", packSize))
	}

	o.writeRepackBundle(ctx, pm, repoID, packHash)

	idxPath := filepath.Join(dir, fmt.Sprintf("pack-%s.idx", packHash))
	revPath := filepath.Join(dir, fmt.Sprintf("pack-%s.rev", packHash))
	bundlePath := filepath.Join(dir, fmt.Sprintf("pack-%s.bundle", packHash))
	return packfile.Set{
		PackPath:   packPath,
		IdxPath:    idxPath,
		RevPath:    revPath,
		BundlePath: bundlePath,
	}, true, nil
}

// writeRepackBundle writes or refreshes the per-pack bundle advertising the
// repo's default-branch tip. The repack output is a full snapshot from the
// receiver's POV — no prereq. Bundle write is advisory: errors are logged
// WARN and never surfaced. nil refRead (tests / in-memory storage) skips
// the write, as does a tip that is not present in the pack.
func (o *LocalStorage) writeRepackBundle(ctx context.Context, pm *packfile.Manager, repoID repositories.ID, packHash plumbing.Hash) {

