func defaultRepackConfig() repackConfig {
	return repackConfig{
		windowSize: repackWindowSize,
		maxObjSize: repackMaxObjSize,
	}
}

// WithWindowSize overrides the delta sliding window size for repack.
func WithWindowSize(n int) RepackOption {
	return func(c *repackConfig) { c.windowSize = n }
}

// WithWindowBytes caps the delta window by total heap bytes (content + delta
// index) in addition to the entry-count cap. 0 (the default) leaves the window
// bounded only by count, so a window of large objects can pin windowSize ×
// maxObjSize of heap. Setting a budget bounds repack's peak regardless of
// object sizes — the memory-safety lever for large-repo consolidation.
func WithWindowBytes(n int) RepackOption {
	return func(c *repackConfig) { c.windowBytes = n }
}

// WithExternalEntries copies external entries from TakeExternalEntries into
// the output verbatim. The output then has version
// gitwire.PackVersionExternal.
func WithExternalEntries(entries []ExternalEntry) RepackOption {
	return func(c *repackConfig) { c.externals = entries }
}

// withReusableRuns provides pre-found reusable runs from source packfiles.
func withReusableRuns(runs []reusableRun) RepackOption {
	return func(c *repackConfig) { c.reusableRuns = runs }
}

// WithReusableDeltas attaches existing OFS_DELTA entries (from Manager.GetBatchRaw)
// to be copied into the repack output verbatim rather than resolved and
// re-delta-compressed. The map is keyed by object hash. The caller must NOT
// also include these hashes among the resolved objects passed to
// WriteRepackPackfile — an object is either reused here or recomputed there,
// never both. Every delta's immediate base must itself be in the output (a run,
// a resolved object, or another reusable delta); consolidation guarantees this
// because the base is an entry in one of the source packs being consolidated.
func WithReusableDeltas(deltas map[plumbing.Hash]RawDeltaEntry) RepackOption {
	return func(c *repackConfig) {
		c.reusableDeltas = make([]reusableDelta, 0, len(deltas))
		for h, d := range deltas {
			c.reusableDeltas = append(c.reusableDeltas, reusableDelta{
				hash:             h,
				base:             d.BaseHash,
				uncompressedSize: d.UncompressedSize,
				zlibDelta:        d.ZlibDelta,
				sourceOffset:     d.SourceOffset,
			})
		}
	}
}

// RunDeltaDepths exposes the in-run delta chain depths of the runs selected by
// FindAndAttachRuns. Runs are copied verbatim, so an entry's in-run depth is
// also its output depth — the fixed floor under any reused delta chain rooted
// at it.
type RunDeltaDepths struct {
	runs []reusableRun
}

// DepthsFor returns the in-run chain depth of each requested hash that is a
// run entry stored as a delta (depth > 0; other hashes are absent). One scan
// over the run entries; the result is sized by the request, not the runs —
// callers ask only for reuse chain roots (see ReuseChainRoots).
func (r RunDeltaDepths) DepthsFor(hashes map[plumbing.Hash]struct{}) map[plumbing.Hash]int {
	depths := make(map[plumbing.Hash]int)
	for _, run := range r.runs {
		for i, d := range run.depths {
			if d == 0 {
				continue
			}
			if _, want := hashes[run.entries[i].Hash]; want {
				depths[run.entries[i].Hash] = d
			}
		}
	}
	return depths
}

// ReuseChainRoots returns the chain roots of a reusable-delta set: the base
// hashes that are not themselves in the set.
func ReuseChainRoots(deltas map[plumbing.Hash]RawDeltaEntry) map[plumbing.Hash]struct{} {
	roots := make(map[plumbing.Hash]struct{})
	for _, d := range deltas {
		if _, in := deltas[d.BaseHash]; !in {
			roots[d.BaseHash] = struct{}{}
		}
	}
	return roots
}

// FindAndAttachRuns finds reusable runs in the given packfiles for the given
// hashes and returns a RepackOption that attaches them. Objects covered by
// runs are removed from hashSet so the caller can skip resolving them.
// The returned RunDeltaDepths feeds BoundReusableDeltaDepth so reused deltas
// stacked on run entries stay within the writer's depth cap.
func FindAndAttachRuns(ctx context.Context, packs []*Loaded, hashSet map[plumbing.Hash]struct{}, minRun int) (RepackOption, int, RunDeltaDepths, error) {
	runs, err := findReusableRuns(ctx, packs, hashSet, minRun)
	if err != nil {
		return nil, 0, RunDeltaDepths{}, err
	}
	var runObjects int
	for _, r := range runs {
		runObjects += len(r.entries)
	}
	return withReusableRuns(runs), runObjects, RunDeltaDepths{runs: runs}, nil
}

// RepackObject is a resolved object to include in a repack packfile.
type RepackObject struct {
	Hash    plumbing.Hash
	Type    byte   // packfile type: 1=commit, 2=tree, 3=blob, 4=tag
	Content []byte // uncompressed content
	Name    string // filename from tree entry, for delta compression sorting
}

// SortRepackObjects orders objects for delta compression: by type (commits,
// tags, trees, blobs), then basename, full path, and size descending so larger
// objects precede the smaller ones that delta against them. WriteRepackPackfile
// applies this ordering itself; it is exported so callers that split a large
// object set across several WriteRepackPackfile calls can sort the whole set
// first, keeping each contiguous batch grouped as a single-pack repack would be.
func SortRepackObjects(objects []RepackObject) {
	slices.SortFunc(objects, func(a, b RepackObject) int {
		return cmp.Or(
			cmp.Compare(a.Type, b.Type),
			cmp.Compare(path.Base(a.Name), path.Base(b.Name)),
			cmp.Compare(a.Name, b.Name),
			cmp.Compare(len(b.Content), len(a.Content)),
		)
	})
}

