	deltaObjects := len(cfg.reusableDeltas)
	totalObjects := len(objects) + runObjects + deltaObjects + len(cfg.externals)

	if totalObjects == 0 {
		return nil, nil
	}

	span.SetAttributes(
		attribute.Int("objects", totalObjects),
		attribute.Int("run_objects", runObjects),
		attribute.Int("reused_deltas", deltaObjects),
		attribute.Int("external_entries", len(cfg.externals)),
		attribute.Int("window_size", cfg.windowSize),
		attribute.Int("max_obj_size", cfg.maxObjSize),
		attribute.String("object_format", objectFormat.String()),
