	// its chain, so record each base's offset and depth as its object is
	// emitted in Phase 1 or 2. recordBase tracks only bases (bounding the maps
	// to the reused-delta set rather than every object); it is a no-op when
	// there is nothing to reuse. stackHeights lowers a Phase-2 root's own
	// fresh-delta budget by the reused height above it, so root depth plus
	// stacked reuse stays within deltaMaxDepth.
	var outputOffsets map[plumbing.Hash]int64
	var outputDepths map[plumbing.Hash]int
	var stackHeights map[plumbing.Hash]int
	recordBase := func(plumbing.Hash, int64, int) {}
	if deltaObjects > 0 {
		neededBases := make(map[plumbing.Hash]struct{}, deltaObjects)
		for i := range cfg.reusableDeltas {
			neededBases[cfg.reusableDeltas[i].base] = struct{}{}
		}
		outputOffsets = make(map[plumbing.Hash]int64, len(neededBases))
		outputDepths = make(map[plumbing.Hash]int, len(neededBases))
		stackHeights = reuseStackHeights(cfg.reusableDeltas)
		recordBase = func(h plumbing.Hash, off int64, depth int) {
			if _, ok := neededBases[h]; ok {
				outputOffsets[h] = off
				outputDepths[h] = depth
			}
		}
	}

	h := packTrailerHasher(objectFormat)
	ow := &offsetWriter{w: io.MultiWriter(w, h)}

	hdr := makeHeaderSegment(totalObjects)
	if len(cfg.externals) > 0 {
		binary.BigEndian.PutUint32(hdr.hdr[4:8], gitwire.PackVersionExternal)
	}
	if _, err := hdr.WriteTo(ow); err != nil {
		return nil, fmt.Errorf("pack header: %w", err)
	}

	entries := make([]gitpack.IndexEntry, 0, totalObjects)

	// Phase 1: Copy reusable runs as raw byte ranges (no delta computation).
	for _, run := range cfg.reusableRuns {
		runEntries, err := copyRunForRepack(ctx, ow, run)
		if err != nil {
			return nil, fmt.Errorf("copy run: %w", err)
		}
		for i := range runEntries {
			depth := 0
			if i < len(run.depths) {
				depth = run.depths[i]
			}
			recordBase(runEntries[i].Hash, runEntries[i].Offset, depth)
		}
		entries = append(entries, runEntries...)
	}

