		entry := gitpack.IndexEntry{Hash: e.Hash, Offset: ow.offset, CRC32: crc32.ChecksumIEEE(e.Raw)}
		if _, err := ow.Write(e.Raw); err != nil {
			return nil, fmt.Errorf("external entry %s: %w", e.Hash, err)
		}
		entries = append(entries, entry)
	}

	// Sort remaining objects: type, basename, full path, size descending.
	SortRepackObjects(objects)
	// Phase 2: Delta-compress remaining objects. zw and cbuf are reused across
	// every entry (compressor state + compression output buffer).
	var zw *kzlib.Writer
	var cbuf bytes.Buffer
	blobWindow := make([]deltaWindowEntry, 0, cfg.windowSize)
	treeWindow := make([]deltaWindowEntry, 0, cfg.windowSize)
	pool := newDeltaScratchPool()

