// objectFormat selects the hash function used for the packfile's trailing
// checksum (SHA1 → 20-byte trailer, SHA256 → 32-byte trailer).
//
// Objects are sorted by type (commits, tags, trees, blobs) before writing.
// Within trees and blobs, larger objects are written first so they serve as
// delta bases for smaller ones (matching git's strategy).
func WriteRepackPackfile(ctx context.Context, w io.Writer, objects []RepackObject, objectFormat formatcfg.ObjectFormat, opts ...RepackOption) ([]gitpack.IndexEntry, error) {
