// indexBeatsProbe reports whether indexing every pack entry costs less than
// probing each pack per object. Each probe is one index lookup; indexing
// reads every entry once.
func indexBeatsProbe(objectCount, packCount, totalEntries int) bool {
	return objectCount*packCount >= totalEntries
}

// indexPackEntries maps every entry of every loaded pack. It observes
// cancellation between packs: a fetch abandoned here would otherwise read
// every index in the repo.
func (p *packWriter) indexPackEntries(ctx context.Context) (map[plumbing.Hash]packOffset, error) {
	idx := make(map[plumbing.Hash]packOffset)
	for pi, lp := range p.packs {
		if err := ctx.Err(); err != nil {
			return nil, fmt.Errorf("index pack entries cancelled: %w", err)
		}
		entries, err := lp.AllEntries()
		if err != nil {
			continue
		}
		for _, e := range entries {
			if _, ok := idx[e.Hash]; ok {
				continue
			}
			idx[e.Hash] = packOffset{packIdx: pi, offset: e.Offset}
		}
	}
	return idx, nil
}

// sortByPackLocation orders objects by pack and offset so an OFS_DELTA base
// precedes the delta that names it across batch boundaries. Objects in no
// pack keep their order at the end, so the delta window on resolved trees
// and blobs still meets related entries together. Returns how many objects
// no loaded pack holds.
func (p *packWriter) sortByPackLocation(ctx context.Context, objects []PackObject) (unlocated int, err error) {
	located, err := p.locateObjects(ctx, objects)
	if err != nil {
		return 0, err
	}
	slices.SortStableFunc(objects, func(a, b PackObject) int {
		oa, hasA := located[a.Hash]
		ob, hasB := located[b.Hash]
		switch {
		case hasA && hasB:
			return cmp.Or(cmp.Compare(oa.packIdx, ob.packIdx), cmp.Compare(oa.offset, ob.offset))
		case hasA:
			return -1
		case hasB:
			return 1
		default:
			return 0
		}
	})
	for _, o := range objects {
		if _, ok := located[o.Hash]; !ok {
			unlocated++
		}
	}
	return unlocated, nil
}

// reusableRun is a contiguous sequence of packfile entries (in offset order)
// where every entry is in the request set and every OFS_DELTA base falls
// within the run, so internal relative offsets remain valid when copied.
type reusableRun struct {
	pack     *Loaded
	entries  []HashOffset
	depths   []int // in-run delta chain depth per entry, parallel to entries
	startOff int64
	endOff   int64
}

// findReusableRuns uses a two-pass strategy to find the best set of reusable
// runs across all packfiles. Pass 1 scans every packfile and collects all
// candidate runs without claiming any hashes. Pass 2 selects runs longest-
// first, skipping any whose hashes have already been claimed by a longer run.
//
// A run is a contiguous sequence of entries (by offset) where every entry's
// hash is in hashSet, no entry is REF_DELTA (type 7), and every OFS_DELTA's
// base offset falls within the run. Only runs with >= minRun entries are
// considered.
func findReusableRuns(ctx context.Context, packs []*Loaded, hashSet map[plumbing.Hash]struct{}, minRun int) ([]reusableRun, error) {
	_, span := otel.Tracer().Start(ctx, "packfile.findReusableRuns")
	defer span.End()

	// Pass 1: discover all candidate runs across all packfiles.
	candidates, err := discoverCandidateRuns(packs, hashSet, minRun)
	if err != nil {
		return nil, err
	}

	// Pass 2: sort longest-first and greedily select non-overlapping runs.
	slices.SortFunc(candidates, func(a, b reusableRun) int {
		return cmp.Compare(len(b.entries), len(a.entries))
	})

	var runs []reusableRun
	for _, c := range candidates {
		// Check that every hash in this run is still unclaimed.
		allAvailable := true
		for _, e := range c.entries {
			if _, ok := hashSet[e.Hash]; !ok {
				allAvailable = false
				break
			}
		}
		if !allAvailable {
			continue
		}
		runs = append(runs, c)
		for _, e := range c.entries {
			delete(hashSet, e.Hash)
		}
	}

	return runs, nil
}

// buildPackRuns groups a pack's wanted entries — which MUST be sorted by
// ascending offset — into contiguous reusable runs, appending them to runs.
// A run breaks at:
//
//   - a gap in the byte stream (a non-wanted entry between two wanted ones,
//     detected when an entry doesn't start where the previous one ends);
//   - a REF_DELTA (type 7), which can't be reused;
//   - an external entry (type 5): a version 2 pack never carries one, so the
//     caller writes the blob another way;
//   - an OFS_DELTA (type 6) whose base lies before the run start; or
//   - an OFS_DELTA whose in-run chain depth exceeds deltaMaxDepth, so a
//     source pack that already violates the writer's depth cap (ENT-2347)
//     is not copied forward verbatim — the over-deep tail falls out of the
//     run and is re-resolved and re-deltified under the cap instead.
//
// Only runs of >= minRun entries are emitted. f is a reader over the pack;
// nextOffset maps an entry offset to the next entry's offset (pack-end sentinel
// for the last). Used by the generic (discoverCandidateRuns) path; the bitmap
// streamer coalesces the equivalent spans inline in streamBitmapObjects using
// the same break rules.
//
// INVARIANT: the type-6 base-before-run break guards OFS_DELTA validity —
// copying a run whose base lies outside it yields an unresolvable pack.
func buildPackRuns(lp *Loaded, f io.ReaderAt, entries []HashOffset, nextOffset func(int64) int64, minRun int, runs []reusableRun) ([]reusableRun, error) {
	var cur []HashOffset
	var curDepths []int
	var curStart int64
	depthAt := make(map[int64]int)

	flush := func() {
		if len(cur) >= minRun {
			last := cur[len(cur)-1]
			runs = append(runs, reusableRun{
				pack:     lp,
				entries:  cur,
				depths:   curDepths,
				startOff: curStart,
				endOff:   nextOffset(last.Offset),
			})
		}
		cur = nil
		curDepths = nil
		clear(depthAt)
	}

	for _, e := range entries {
		// Gap detection: if this entry doesn't start where the previous wanted
		// entry ends, a non-wanted entry sits between them and the run breaks.
		if len(cur) > 0 && e.Offset != nextOffset(cur[len(cur)-1].Offset) {
			flush()
		}

		objType, baseAbsOff, err := EntryHeader(f, e.Offset)
		if err != nil {
			return nil, fmt.Errorf("entry header at %d: %w", e.Offset, err)
		}

		if objType == 7 || objType == externalEntryType { // REF_DELTA or external entry — can't reuse
			flush()
			continue
		}
		depth := 0
		if objType == 6 {
			if len(cur) == 0 || baseAbsOff < curStart {
				flush()
				continue
			}
			baseDepth, ok := depthAt[baseAbsOff]
			if !ok || baseDepth+1 > deltaMaxDepth {
				flush()
				continue
			}
			depth = baseDepth + 1
		}

		if len(cur) == 0 {
			curStart = e.Offset
		}
		cur = append(cur, e)
		curDepths = append(curDepths, depth)
		depthAt[e.Offset] = depth
	}
	flush()
	return runs, nil
}

// discoverCandidateRuns scans all packfiles for contiguous runs of requested
// objects without mutating hashSet. Returns all candidate runs that meet the
// minimum length threshold. Each pack's entries are pre-filtered to the wanted
// set, then grouped by buildPackRuns (gap detection reproduces the
// "consecutive wanted entries" runs the full-scan approach would find).
func discoverCandidateRuns(packs []*Loaded, hashSet map[plumbing.Hash]struct{}, minRun int) ([]reusableRun, error) {
	var candidates []reusableRun

	for _, lp := range packs {
		allEntries, err := lp.AllEntries()
		if err != nil || len(allEntries) == 0 {
			continue
		}

		// Pre-filter to wanted entries, preserving offset order (AllEntries is
		// offset-ordered). Filtered in place — AllEntries returns a fresh slice.
		wanted := allEntries[:0]
		for _, e := range allEntries {
			if _, ok := hashSet[e.Hash]; ok {
				wanted = append(wanted, e)
			}
		}
		if len(wanted) == 0 {
			continue
		}

		nextOffset, err := lp.nextOffsetFunc()
		if err != nil {
			return nil, fmt.Errorf("next offset for %s: %w", lp.PackPath(), err)
		}

		f, err := os.Open(filepath.Clean(lp.PackPath()))
		if err != nil {
			return nil, fmt.Errorf("open pack %s: %w", lp.PackPath(), err)
		}
		candidates, err = buildPackRuns(lp, f, wanted, nextOffset, minRun, candidates)
		_ = f.Close()
		if err != nil {
			return nil, err
		}
	}

	return candidates, nil
}

// copyPackfileRun copies a contiguous run of packfile entries as a single
// byte range from the source packfile into the output writer. Populates
// outputOffsets with each entry's position in the output.
func copyPackfileRun(
	ow *offsetWriter,
