// GetBatchRawDeltas returns the raw compressed delta bytes for those gitHashes
// stored as OFS_DELTAs in packs, keyed by object hash. Hashes that are not
// OFS_DELTAs (non-delta entries, REF_DELTAs, or absent) are simply omitted —
// the caller resolves them another way. Unlike GetBatchRaw it never reads a
// non-delta entry's zlib stream, so repack can extract reusable deltas without
// the wasted read+copy for objects it will resolve fully anyway.
func (w *Manager) GetBatchRawDeltas(packs []*Loaded, gitHashes []plumbing.Hash) (map[plumbing.Hash]RawDeltaEntry, error) {
	foundDelta := make(map[plumbing.Hash]RawDeltaEntry)
	remaining := make(map[plumbing.Hash]struct{}, len(gitHashes))
	for _, h := range gitHashes {
		remaining[h] = struct{}{}
	}

	for _, lp := range packs {
		if len(remaining) == 0 {
			break
		}

		var inThisPack []HashOffset
		for h := range remaining {
			if off, err := lp.idx.FindOffset(h); err == nil {
				inThisPack = append(inThisPack, HashOffset{Hash: h, Offset: off})
			}
		}
		if len(inThisPack) == 0 {
			continue
		}

		f, err := lp.getRawFile()
		if err != nil {
			return nil, err
		}
		findNextOffset, err := lp.nextOffsetFunc()
		if err != nil {
			return nil, fmt.Errorf("next offset func for %s: %w", lp.packPath, err)
		}

		for _, ho := range inThisPack {
			objType, uncompressedSize, headerLen, err := readEntryHeader(f, ho.Offset)
			if err != nil {
				return nil, fmt.Errorf("read header for %s: %w", ho.Hash, err)
			}
			if objType != 6 { // only OFS_DELTA is reusable here; leave the rest
				continue
			}

			negOffset, offsetBytesLen, err := readOFSDeltaOffsetAt(f, ho.Offset+int64(headerLen))
			if err != nil {
				return nil, fmt.Errorf("read delta offset for %s: %w", ho.Hash, err)
			}
			baseHash, err := lp.idx.FindHash(ho.Offset - negOffset)
			if err != nil {
				return nil, fmt.Errorf("find base hash at offset %d for %s: %w", ho.Offset-negOffset, ho.Hash, err)
			}
			if baseHash.IsZero() {
				// A corrupt index names the base as zero; the delta can't be
				// reused by name. Leave it for full (offset-based) resolution.
				continue
			}

			zlibStart := ho.Offset + int64(headerLen) + int64(offsetBytesLen)
			zlibData, err := readZlibRange(f, zlibStart, findNextOffset(ho.Offset), ho.Hash)
			if err != nil {
				return nil, err
			}

			foundDelta[ho.Hash] = RawDeltaEntry{
				UncompressedSize: uncompressedSize,
				BaseHash:         baseHash,
				ZlibDelta:        zlibData,
				SourceOffset:     ho.Offset,
			}
			delete(remaining, ho.Hash)
		}
	}

	return foundDelta, nil
}

