// loose-format bytes. Returns ErrNotFound if the object is not in any packfile.
func GetFromLoaded(packs []*Loaded, gitHash plumbing.Hash, cache *ResolverCache) ([]byte, error) {
	obj, err := ResolveFromLoaded(packs, gitHash, cache)
	if err != nil {
		return nil, err
	}
	return EncodeLooseObject(gitHash, obj)
}

// EncodeLooseObject encodes a resolved object into loose (stored) format: the
// zlib-compressed "type size\0content" that Badger and the peer protocol
// carry. The object format follows from the hash length.
func EncodeLooseObject(h plumbing.Hash, obj ResolvedObject) ([]byte, error) {
	//nolint:gosec // resolved types are always 1-4
	return encodeLoose(plumbing.ObjectType(obj.Type), obj.Content, formatForHashSize(h.Size()))
}

