func VerifyHashesInPackfile(packPath string, hashes []plumbing.Hash) error {
	lp, err := allocSingleIdx(packPath)
	if err != nil {
		return fmt.Errorf("load packfile for verification: %w", err)
	}
	defer func() { _ = lp.Close() }()

	for _, h := range hashes {
