}

// allocSingleIdx loads a single pack (index + pack body) by its .pack path,
// rebuilding a missing index from the .pack if needed. The returned Loaded
// carries a reference the caller must Close.
func allocSingleIdx(packPath string) (*Loaded, error) {
	dir := filepath.Dir(packPath)
	name := filepath.Base(packPath) // pack-<hash>.pack
	packHash := packHashFromFilename(name)
	lp, err := allocLoaded(dir, packHash, true /*rebuild*/)
	if err != nil {
		return nil, fmt.Errorf("load pack %s: %w", packPath, err)
	}
	return lp, nil
}

