func (s *Service) TriggerRepack(ctx context.Context, req *connect.Request[adminpb.TriggerRepackRequest]) (*connect.Response[adminpb.TriggerRepackResponse], error) {
	accountID := callerAccountID(ctx)

	owner := req.Msg.GetOwner()
	repo := req.Msg.GetRepo()
	if owner == "" || repo == "" {
		return nil, connect.NewError(connect.CodeInvalidArgument, errors.New("owner and repo are required"))
	}

	repoID, err := s.resolveOwnerRepoToID(ctx, owner, repo)
	if err != nil {
		return nil, err
	}

	slogutil.Info(ctx, "repack triggered", slog.String("repo", owner+"/"+repo), slog.String("repo_id", repoID.String()), slog.String("triggered_by", accountID.String()))

	if s.DissPeer == nil {
		return nil, connect.NewError(connect.CodeFailedPrecondition, errors.New("repack requires a DISS peer"))
	}

	if s.RefstoreBackend == nil {
		return nil, connect.NewError(connect.CodeFailedPrecondition, errors.New("repack requires a refstore backend"))
	}

