// chainMaintain is the maintenance flow for the geometric strategy
// (ENT-1072 + ENT-1624, the port of git 2.55's `repack
// --write-midx=incremental --geometric`): rollup candidacy comes from
// planChainGeometric — uncovered packs always, logical-tip packs only when
// the tip holds >= midxNewLayerThreshold packs, deeper layers never — and the
// chain is compacted by the layer merge condition instead of flattened
// (suffix-first here, then chainMidCompactPass for drifted layers below the
// tip). Deep-layer packs are never candidates, so consolidateWriteOnly never
// reads them: a pack's bytes are rewritten on a logarithmic schedule
// regardless of how often maintenance runs.
//
// allowRollup distinguishes GeometricRepack (packs may be consolidated) from
// CollapseMidx (metadata-only: append, compact, or noop).
//
// A repo with no chain to plan against runs chainBootstrap; degraded states
// discovered after planning finish on an inline flat rebuild, so a rollup is
// consolidated at most once per pass either way.
func (o *LocalStorage) chainMaintain(ctx context.Context, repoID repositories.ID, view []packfile.Set, pt *passTips, allowRollup bool) error {
	ctx, span := otel.Tracer().Start(ctx, "objstore.LocalStorage.chainMaintain")
	defer span.End()

	pm := o.PackfileManager()
	eligible := eligiblePacks(view)
	span.SetAttributes(
		attribute.String("repo_id", repoID.String()),
		attribute.Int("eligible_packs", len(eligible)),
		attribute.Bool("allow_rollup", allowRollup),
	)

	// Nothing to plan against. No tips: a new chain layer would be bitmap-less
	// and immutable, so it would never self-heal — bootstrap installs the MIDX
	// bitmap-less instead (ENT-1022) and the next pass with tips rebuilds it.
	// No MIDX (or an empty one): this is the repo's first structural pass, and
	// bootstrap writes the flat MIDX later passes append onto.
	var layerCounts []uint32
	var layerPacks [][]string
	hasTips := pt.hasTips(ctx)
	if hasTips {
		if mi, lerr := pm.LoadMidx(repoID); lerr == nil && mi != nil {
			layerCounts = mi.LayerObjectCounts()
			layerPacks = mi.LayerPackNames()
			_ = mi.Close()
		}
	}
	depth := len(layerCounts)
	if depth == 0 {
		reason := "bootstrap"
		if !hasTips {
			reason = "no-tips"
		}
		return o.chainBootstrap(ctx, span, repoID, eligible, pt, reason, allowRollup)
	}

	counts, err := packObjectCounts(eligible)
	if err != nil {
		return err
	}
	countByName := make(map[string]uint64, len(eligible)+1)
	for i, s := range eligible {
		countByName[s.IdxName()] = uint64(counts[i])
	}
	plan := planChainGeometric(layerCounts, layerPacks, eligible, midxNewLayerThreshold, geometricFactor)
	span.SetAttributes(
		attribute.Int("midx.depth", depth),
		attribute.Int("midx.chain.tip_start", plan.tipStart),
		attribute.Int("midx.chain.tip_packs", plan.tipPacks),
		attribute.Bool("midx.chain.tip_engaged", plan.tipEngaged),
		attribute.Int("midx.chain.candidates", len(plan.candidates)),
	)

	// Roll up candidates only.
	var rollupSets []packfile.Set
	rolled := make(map[string]bool)
	rolledCovered := false
	if allowRollup && len(plan.candidates) >= 2 {
		candCounts := make([]uint32, len(plan.candidates))
		for k, i := range plan.candidates {
			candCounts[k] = counts[i]
		}
		for _, k := range geometricRollup(candCounts, geometricFactor) {
			i := plan.candidates[k]
			rollupSets = append(rollupSets, eligible[i])
			rolled[eligible[i].IdxName()] = true
			if plan.coveredLayer[i] >= 0 {
				rolledCovered = true
			}
		}
	}
	span.SetAttributes(attribute.Int("rollup_packs", len(rollupSets)))

	var merged []packfile.Set // zero or one set
	if len(rollupSets) >= 2 {
		newView, err := o.consolidateWriteOnly(ctx, repoID, rollupSets, pt.tips.All())
		if err != nil {
			return fmt.Errorf("consolidate rollup: %w", err)
		}
		if repackAbortTestHook != nil {
			if err := repackAbortTestHook("geo-pack-written"); err != nil {
				return err
			}
		}
		if len(newView) == 1 {
			merged = newView
		} else {
			// Declined (rollup holds no objects to consolidate): treat as no
			// rollup rather than falling back, so no other strategy re-reads
			// these packs with different candidacy.
			rollupSets, rolled, rolledCovered = nil, make(map[string]bool), false
		}
	} else {
		rollupSets = nil
	}

	// Packs entering the new tip besides those re-listed from dropped layers:
	// the merged pack and any uncovered survivors. The merged pack seeds the
	// cascade with the pre-dedup sum of its input pack counts — git 2.55's
	// form (repack-midx.c: step.objects_nr += p->num_objects over the packs
	// below the split) — not its own post-dedup on-disk count. On
	// duplicate-heavy push streams the inflated seed folds deeper, buying
	// git's duplicate reclamation at the cost of re-listing byte-heavy layers
	// into the tip, where candidacy can rewrite their bytes;
	// consolidate.dup_entries and midx.chain.tip.retained_dup_entries measure
	// that inflation from prod, and the ADR 20260617 amendment records the
	// tighter post-dedup seed as the candidate divergence if the telemetry
	// shows the eager cascade re-rewriting byte-heavy packs.
	var entering []packfile.Set
	var enteringObjs uint64
	if merged != nil {
		mc, err := packObjectCounts(merged)
		if err != nil {
			return err
		}
		entering = append(entering, merged[0])
		for _, s := range rollupSets {
			enteringObjs += countByName[s.IdxName()]
		}
		countByName[merged[0].IdxName()] = uint64(mc[0])
	}
	for i, s := range eligible {
		if plan.coveredLayer[i] == -1 && !rolled[s.IdxName()] {
			entering = append(entering, s)
			enteringObjs += uint64(counts[i])
		}
	}

	// Drop the whole logical tip when any of its packs was rolled up (the old
	// tip is no longer usable; its survivors move into the new layer — git's
	// rule), then extend by the merge cascade. Object totals are pre-dedup
	// upper bounds throughout, matching git: an overestimate only folds more
	// (metadata-only compaction), never less, so the merge invariant holds
	// either way.
	dropLayers := 0
	newTipObjs := enteringObjs
	if rolledCovered {
		dropLayers = depth - plan.tipStart
		for i, s := range eligible {
			if li := plan.coveredLayer[i]; li >= plan.tipStart && !rolled[s.IdxName()] {
				newTipObjs += uint64(counts[i])
			}
		}
	}
	dropLayers, newTipObjs = mergeCascade(layerCounts, dropLayers, newTipObjs, geometricFactor)
	_ = newTipObjs

	// Pure-compaction kick: nothing new entered, but the logical tip is
	// fragmented across >= 2 layers — fold it so depth returns to the merge
	// fixpoint. This is what CollapseMidx exists for; on the rollup level it
	// is a cheap tidy-up in the same pass.
	if dropLayers == 0 && len(entering) == 0 && depth-plan.tipStart >= 2 {
		dropLayers = depth - plan.tipStart
	}

	// Both apply paths below delete this set. Subtract against the new tip
	// (never delete rollupSets wholesale): consolidation may have reused a
	// rollup member as its output, and the new layer references it.
	var stale []packfile.Set

	midxStage := "geo-midx-written"
	if !allowRollup {
		midxStage = "compact-midx-written"
	}

	// Assemble the new tip layer's packs: entering + re-listed (not rolled
	// up) packs of the dropped layers.
	newTipSets := slices.Clone(entering)
	if dropLayers > 0 {
		viewByName := make(map[string]packfile.Set, len(eligible))
		for _, s := range eligible {
			viewByName[s.IdxName()] = s
		}
		for li := depth - dropLayers; li < depth; li++ {
			for _, name := range layerPacks[li] {
				if rolled[name] {
					continue
				}
				s, ok := viewByName[name]
				if !ok {
					// A layer references a pack missing from the on-disk
					// view. Should be unreachable (maintenance never deletes
					// a pack its MIDX references); repair via flat rebuild.
					return o.chainFlatRebuild(ctx, span, repoID, "missing-pack", len(rollupSets),
						chainFlatPacks(eligible, rolled, merged),
						subtractSetsByIdxName(rollupSets, merged), pt, midxStage, allowRollup)
				}
				newTipSets = append(newTipSets, s)
			}
		}
	}
	newTipSets = dedupSetsByIdxName(newTipSets)
	stale = subtractSetsByIdxName(rollupSets, newTipSets)

	// Apply.
	var action string
	var introduced int
	switch {
	case dropLayers == 0 && len(entering) == 0:
		span.SetAttributes(
			attribute.String("midx.geometric.path", "chain"),
			attribute.String("midx.geometric.chain_action", "noop"),
		)
		slogutil.Info(ctx, "maintenance: chain already at merge fixpoint, nothing to do",
			slog.String("repo_id", repoID.String()),
			slog.Int("depth", depth))
		// The tip is settled, but lower layers may have drifted (pack
		// expiry): run the mid-chain pass before declaring the repo done.
		o.chainMidCompactPass(ctx, repoID, pm)
		return nil

	case dropLayers == depth:
		// The cascade absorbed every layer: no base remains, so this is a
		// flat rebuild of the whole repo (the same cost class).
		return o.chainFlatRebuild(ctx, span, repoID, "full-cascade", len(rollupSets),
			chainFlatPacks(eligible, rolled, merged), stale, pt, midxStage, allowRollup)

	case dropLayers == 0:
		// New content, no layer replaced: plain append. On the CollapseMidx
		// path (allowRollup=false) this means a pass triggered
		// *because* depth crossed chainCompactDepthTrigger can transiently
		// grow the chain by one when an uncovered pack exists and the tip is
		// already at its merge fixpoint — appending the uncovered pack is
		// still the right move (it must be indexed, and rewriting a
		// fixpoint tip for it would defeat the strategy). Depth is reeled
		// back by the merge cascade once enough small layers accumulate.
		n, err := pm.AppendMidxLayer(ctx, repoID, entering, pt.tips)
		introduced = n
		switch {
		case err == nil:
			action = "append-only"
			if merged != nil {
				action = "rollup-append"
			}
		case errors.Is(err, packfile.ErrNoBaseForAppend),
			errors.Is(err, packfile.ErrAppendClosureIncomplete):
			return o.chainFlatRebuild(ctx, span, repoID, "no-base", len(rollupSets),
				chainFlatPacks(eligible, rolled, merged), stale, pt, midxStage, allowRollup)
		default:
			return fmt.Errorf("append midx layer: %w", err)
		}

	default:
		compactTips := pt.full(ctx)
		logBitmapEncodeTips(ctx, repoID, compactTips)
		n, err := pm.CompactChainSuffix(ctx, repoID, newTipSets, dropLayers, compactTips)
		introduced = n
		switch {
		case err == nil:
			action = "compact-only"
			if merged != nil {
				action = "rollup-compact"
			}
		case errors.Is(err, packfile.ErrNoBaseForAppend),
			errors.Is(err, packfile.ErrAppendClosureIncomplete):
			// Same fallbacks as the append arm: no usable base, or refs
			// ahead of objects (ENT-1071) — the flat rebuild installs a
			// MIDX without a bitmap (ENT-1022) instead of failing the
			// pass, which would recur until the objects replicate.
			return o.chainFlatRebuild(ctx, span, repoID, "no-base", len(rollupSets),
				chainFlatPacks(eligible, rolled, merged), stale, pt, midxStage, allowRollup)
		default:
			return fmt.Errorf("compact chain suffix: %w", err)
		}
	}

	if repackAbortTestHook != nil {
		if err := repackAbortTestHook(midxStage); err != nil {
			return err
		}
	}
	if len(stale) > 0 {
		if geometricDeleteTestHook != nil {
			geometricDeleteTestHook()
			geometricDeleteTestHook = nil
		}
		deletePackSets(ctx, stale)
	}
	if allowRollup && repackAbortTestHook != nil {
		if err := repackAbortTestHook("geo-packs-deleted"); err != nil {
			return err
		}
	}

	// Retained duplication: tip-pack index entries whose objects the kept
	// chain already covers. Together with consolidate.dup_entries this is the
	// duplication ratio of the repo's push stream — the quantity that decides
	// whether git's pre-dedup cascade seed (above) keeps dragging byte-heavy
	// layers into the tip. The ADR 20260617 amendment records the tighter
	// post-dedup seed as the candidate divergence if prod telemetry shows
	// that; until then the seed stays canonical git 2.55.
	var tipPackEntries uint64
	for _, s := range newTipSets {
		tipPackEntries += countByName[s.IdxName()]
	}
	retainedDup := int64(tipPackEntries) - int64(introduced)

	span.SetAttributes(
		attribute.String("midx.geometric.path", "chain"),
		attribute.String("midx.geometric.chain_action", action),
