		// flat rebuild of the whole repo (the same cost class).
		return o.chainFlatRebuild(ctx, span, repoID, "full-cascade", len(rollupSets),
			chainFlatPacks(eligible, rolled, merged), stale, pt, midxStage, allowRollup)

	case dropLayers == 0:
