		}
	}

	if repackAbortTestHook != nil {
		if err := repackAbortTestHook(midxStage); err != nil {
			return err
		}
	}
	if len(stale) > 0 {
		if geometricDeleteTestHook != nil {
			geometricDeleteTestHook()
			geometricDeleteTestHook = nil
		}
		deletePackSets(ctx, stale)
	}
