		attribute.String("midx.geometric.path", "chain"),
		attribute.String("midx.geometric.chain_action", action),
		attribute.Int("midx.chain.drop_layers", dropLayers),
		attribute.Int("midx.chain.keep_layers", depth-dropLayers),
		attribute.Int("midx.chain.new_tip_packs", len(newTipSets)),
		attribute.Int("midx.chain.tip.introduced_objects", introduced),
