		slog.String("repo_id", repoID.String()),
		slog.String("action", action),
		slog.Int("rolled_up_packs", len(rollupSets)),
		slog.Int("dropped_layers", dropLayers),
		slog.Int("new_tip_packs", len(newTipSets)),
		slog.Int("introduced_objects", introduced),
		slog.Int64("retained_dup_entries", retainedDup),
