// geometric rollup over the eligible packs *is* the chain plan for this state.
// reason is the flat_reason recorded on the span ("bootstrap" or "no-tips").
func (o *LocalStorage) chainBootstrap(ctx context.Context, span trace.Span, repoID repositories.ID, eligible []packfile.Set, pt *passTips, reason string, allowRollup bool) error {
	if len(eligible) == 0 {
		return nil
	}

	var rollupSets, merged []packfile.Set
	rolled := make(map[string]bool)
	if allowRollup && len(eligible) >= 2 {
		counts, err := packObjectCounts(eligible)
		if err != nil {
			return err
		}
		for _, i := range geometricRollup(counts, geometricFactor) {
			rollupSets = append(rollupSets, eligible[i])
			rolled[eligible[i].IdxName()] = true
		}
		if len(rollupSets) < 2 {
			// Already geometric — nothing worth rewriting; just index it.
			rollupSets, rolled = nil, make(map[string]bool)
		}
	}
	if len(rollupSets) >= 2 {
		newView, err := o.consolidateWriteOnly(ctx, repoID, rollupSets, pt.tips.All())
		if err != nil {
			return fmt.Errorf("consolidate rollup: %w", err)
		}
		if repackAbortTestHook != nil {
			if err := repackAbortTestHook("geo-pack-written"); err != nil {
				return err
			}
		}
		if len(newView) == 1 {
			merged = newView
		} else {
			// Declined (the rollup packs hold no objects to consolidate):
			// treat as no rollup and index the eligible packs as they are.
			rollupSets, rolled = nil, make(map[string]bool)
		}
	}

	midxStage := "geo-midx-written"
	if !allowRollup {
		midxStage = "compact-midx-written"
	}
	// Subtract, don't delete rollupSets wholesale: consolidation may have
	// reused a rollup member as its output, and the MIDX references it.
	return o.chainFlatRebuild(ctx, span, repoID, reason, len(rollupSets),
		chainFlatPacks(eligible, rolled, merged),
		subtractSetsByIdxName(rollupSets, merged), pt, midxStage, allowRollup)
