// chainFlatPacks is the pack set a chainMaintain flat fallback indexes: every
// eligible pack that wasn't rolled up, plus the consolidation output (which
// may itself be a reused rollup member — dedup handles that).
func chainFlatPacks(eligible []packfile.Set, rolled map[string]bool, merged []packfile.Set) []packfile.Set {
	packs := make([]packfile.Set, 0, len(eligible)+1)
	packs = append(packs, merged...)
	for _, s := range eligible {
		if !rolled[s.IdxName()] {
			packs = append(packs, s)
		}
	}
	return dedupSetsByIdxName(packs)
}

