package objstore

import (
	"sort"

	"entire.io/packfile"
)

// geometricFactor is the size ratio the pack progression maintains: each
// surviving pack holds at least this many times the objects of the next-smaller
// pack. Matches git's default `repack --geometric=2`. A constant, not config —
// we tune by changing code (ADR 20260317 §5 convention).
const geometricFactor = 2

// eligiblePacks returns the packs that participate in the geometric size
// progression. Today that's every pack. When cruft packs land (ENT-681) they
// are a separate class on their own expiry cadence and must be excluded from the
// progression — that exclusion happens here and nowhere else, so geometricRollup
// and the chain logic never learn about reachability.
func eligiblePacks(sets []packfile.Set) []packfile.Set { return sets }

// geometricRollup returns the indices (into counts) of the packs that must be
// rolled up into one new pack so the survivors form a progression where each
// pack holds at least factor times the objects of the next-smaller. It mirrors
// git's split_pack_geometry (builtin/repack.c): sort by object count ascending,
// find the largest suffix that already forms a progression, then grow the
// rolled-up prefix rightward — absorbing each next pack while it would violate
// the progression against the accumulating new pack.
//
// Worked example (factor 2), packs [1,2,2,4,32]: the break is at the second 2
// (2 < 2*2), so the prefix [1,2] rolls up (sum 3); 2 < 2*3 absorbs to 5; 4 < 2*5
// absorbs to 9; 32 >= 2*9 stops. Rollup = {1,2,2,4} (sum 9), survivors [9,32].
//
// Returns nil when fewer than two packs would be merged (already geometric, or
// nothing useful to do). The returned indices are sorted ascending and refer to
// the original counts slice, regardless of input order.
func geometricRollup(counts []uint32, factor int) []int {
	n := len(counts)
	if n < 2 || factor < 2 {
		return nil
	}

	// order[k] = original index of the k-th smallest pack. Stable so equal
	// counts keep input order (deterministic rollup selection).
	order := make([]int, n)
	for i := range order {
		order[i] = i
	}
	sort.SliceStable(order, func(a, b int) bool {
		return counts[order[a]] < counts[order[b]]
	})
	weight := func(k int) uint64 { return uint64(counts[order[k]]) }

	// Walk down from the largest pack; the progression breaks at the first
	// pack that holds fewer than factor times its smaller neighbour. Packs at
	// or below that boundary are the initial rollup prefix. No break => the
	// whole set is already geometric.
	split := 0
	for i := n - 1; i > 0; i-- {
		if weight(i) < uint64(factor)*weight(i-1) {
			split = i
			break
		}
	}
	if split == 0 {
		return nil
	}

	// Grow the rolled-up prefix: its merged weight is `total`, and any pack to
	// its right smaller than factor*total would break the progression against
	// the new pack, so absorb it too.
	var total uint64
	for i := range split {
		total += weight(i)
	}
	for i := split; i < n; i++ {
		cur := weight(i)
		if cur >= uint64(factor)*total {
			break
		}
		total += cur
		split++
	}

	if split < 2 {
		return nil
	}

	rollup := make([]int, split)
	for i := range split {
		rollup[i] = order[i]
	}
	sort.Ints(rollup)
	return rollup
}

// The geometric strategy (ENT-1072) ports git 2.55's
// `repack --write-midx=incremental --geometric` semantics: rollup candidacy is
// gated by MIDX chain state instead of considering every pack. Uncovered packs
// are always candidates; packs in the logical tip (below) are candidates only
// when the tip holds >= midxNewLayerThreshold packs; deeper layers' packs are
// never candidates, so a pack's bytes are rewritten on a logarithmic schedule
// no matter how often maintenance runs. The functions here are the pure
// planning half; objstore/repack.go's chainMaintain applies the plan.

// logicalTipStart returns the index of the first layer of the chain's logical
// tip: the trailing suffix that git 2.55's write-time layer merge condition
// would already have merged into one layer. git applies the condition on every
// incremental-MIDX write, so its physical tip *is* this fixpoint; entiredb's
// per-push AppendMidxLayer never merges, making the physical tip an artifact
// of append granularity. Candidacy therefore keys off the logical tip, a pure
// function of chain shape.
//
// The merge condition matches git's integer-division form (repack-midx.c,
// repack_make_midx_compaction_plan): absorb the next-deeper layer while the
// accumulated object count is at least that layer's count divided by factor.
func logicalTipStart(layerCounts []uint32, factor int) int {
	i := len(layerCounts) - 1
	if i <= 0 || factor < 2 {
		return 0
	}
	acc := uint64(layerCounts[i])
	for i > 0 && acc >= uint64(layerCounts[i-1])/uint64(factor) {
		i--
		acc += uint64(layerCounts[i])
	}
	return i
}

// chainGeoPlan is the chain-gated strategy's candidacy decision, computed from
// chain shape and the eligible pack list only.
type chainGeoPlan struct {
	tipStart   int  // layers[tipStart:] form the logical tip
	tipPacks   int  // packs owned by the logical tip
	tipEngaged bool // tipPacks >= threshold: tip packs are rollup candidates

	// candidates are indices into eligible: every uncovered pack, plus the
	// logical tip's packs when tipEngaged.
	candidates []int

	// coveredLayer maps each eligible index to its owning layer, or -1 for a
	// pack no layer covers (freshly pushed / not yet appended).
	coveredLayer []int
}

// planChainGeometric computes chain-gated rollup candidacy. layerCounts and
// layerPacks describe the chain base→tip (MidxIndex.LayerObjectCounts /
// LayerPackNames); eligible is the on-disk pack view. The threshold counts
// logical-tip packs only — uncovered packs are always candidates and never
// count toward the gate, matching git 2.55, where the threshold specifically
// batches tip-layer rewrites while fresh packs roll up cheaply every run.
//
//nolint:unparam // factor is always geometricFactor today; kept so the planner stays a pure function of its inputs, like geometricRollup.
func planChainGeometric(layerCounts []uint32, layerPacks [][]string,
	eligible []packfile.Set, threshold, factor int) chainGeoPlan {
	owner := make(map[string]int)
	for li, packs := range layerPacks {
		for _, p := range packs {
			owner[p] = li
		}
	}

	plan := chainGeoPlan{tipStart: logicalTipStart(layerCounts, factor)}
	for _, packs := range layerPacks[plan.tipStart:] {
		plan.tipPacks += len(packs)
	}
	plan.tipEngaged = plan.tipPacks >= threshold

	plan.coveredLayer = make([]int, len(eligible))
	for i, s := range eligible {
		li, covered := owner[s.IdxName()]
		if !covered {
			plan.coveredLayer[i] = -1
			plan.candidates = append(plan.candidates, i)
			continue
		}
		plan.coveredLayer[i] = li
		if plan.tipEngaged && li >= plan.tipStart {
			plan.candidates = append(plan.candidates, i)
		}
	}
	return plan
}

// mergeCascade extends dropLayers deeper while the new tip satisfies the layer
// merge condition against the next-deeper layer, returning the final drop
// count and accumulated object total. newTipObjs starts as the object count
// entering the new tip layer; callers pass pre-dedup pack counts, an upper
// bound that only makes the cascade marginally more eager (more metadata-only
// compaction), never less.
//
// A zero seed with nothing already dropped returns immediately: an empty
// merge set violates nothing, and letting it fall into the loop would fold a
// sub-factor tip spuriously — for a layer of fewer than factor objects the
// integer division makes the condition read 0 < 0, so a settled [big, tiny]
// chain would be "compacted" into an identical shape on every pass instead
// of reaching the noop fixpoint that logicalTipStart already reports for the
// same chain. git 2.55 has the same truncation quirk (repack-midx.c
// steps:write: an empty plan absorbs a sub-factor tip into the WRITE step),
// but there it is harmless — the rewrite is content-addressed to the same
// checksum and git's cleanup is a keep-list sweep — whereas here it ran on
// every scheduled pass. Diverging from git's literal arithmetic converges
// with its observable fixpoint.
func mergeCascade(layerCounts []uint32, dropLayers int, newTipObjs uint64, factor int) (int, uint64) {
	if factor < 2 || (newTipObjs == 0 && dropLayers == 0) {
		return dropLayers, newTipObjs
	}
	for dropLayers < len(layerCounts) {
		next := uint64(layerCounts[len(layerCounts)-1-dropLayers])
		if newTipObjs < next/uint64(factor) {
			break
		}
		newTipObjs += next
		dropLayers++
	}
	return dropLayers, newTipObjs
}

// compactRanges ports the second phase of git 2.55's incremental-MIDX
// compaction plan (repack-midx.c, the "steps:rest" loop): after the tip-side
// work has settled, walk the remaining chain top-down and group adjacent
// layers whose merged size still violates the merge condition against the
// layer below the group. Each emitted [lo, hi] range (inclusive, base-first
// indices into layerCounts) merges into one layer; a layer that already sits
// geometrically under its lower neighbor is kept as-is (git's COPY step,
// omitted here). Ranges cover layerCounts[0:n] — the caller passes n = the
// first tip layer's index so the tip, which the suffix path owns, is never
// grouped.
//
// The condition is the same integer-division form as logicalTipStart and
// mergeCascade: a group may stop above layer j-1 only once its accumulated
// size is < layerCounts[j-1]/factor. Ranges come back top-down (descending
// hi); executing them in that order keeps every later range's indices valid,
// because merging [lo, hi] shifts only positions above hi.
func compactRanges(layerCounts []uint32, n, factor int) [][2]int {
	if factor < 2 {
		return nil
	}
	var ranges [][2]int
	for top := n - 1; top >= 0; {
		var acc uint64
		cur := top
		for {
			proposed := acc + uint64(layerCounts[cur])
			if cur == 0 {
				// Chain bottom: nothing below to violate against; the group
				// absorbs it and stops (git's !next->base_midx break).
				break
			}
			if proposed < uint64(layerCounts[cur-1])/uint64(factor) {
				// The group merged through cur sits geometrically under the
				// layer below it — include cur and stop.
				break
			}
			acc = proposed
			cur--
		}
		if cur < top {
			ranges = append(ranges, [2]int{cur, top})
		}
		top = cur - 1
	}
	return ranges
}

