// queued or running entry for the same repo (heap-only, no I/O). A running repo's
// new work waits in the re-run slot so it is never dispatched to a second worker.
func (p *MaintenancePool) runJob(job *maintJob) {
	// Clear the entry at pickup, not completion, so a request arriving mid-run
	// re-enters and reaches the re-run slot; the job pointer is the worker's from
	// here, which is why the dispatcher does not do this. Fold in the tips
	// debounced meanwhile. A higher level is not folded: lane routing is by
	// level, so it is requeued as its own request and reaches the re-run slot.
	if e := p.clearInFlight(job.repoID); e != nil {
		job.tips = coalesceTips(job.tips, e.tips)
		if e.level > job.level {
			p.submit(enqueueReq{
				repoID: job.repoID, level: e.level, source: e.levelSource,
				tips: job.tips, at: time.Now(), bypassGate: e.ungated,
			})
