		job.tips = coalesceTips(job.tips, e.tips)
		if e.level > job.level {
			p.submit(enqueueReq{
				repoID: job.repoID, level: e.level, source: e.levelSource,
				tips: job.tips, at: time.Now(), bypassGate: e.ungated,
			})
		}
	}

	// Hold the close barrier across tip resolution + RunMaintenance (both read
	// Badger/mmaps) so the job can't race LocalStorage.Close (ENT-966).
	release, err := p.storage.HoldCloseBarrier()
	if err != nil {
		return
	}
	defer release()

	ctx, span := entireotel.Tracer().Start(p.ctx, "objstore.maintenancepool.job",
		trace.WithAttributes(
			attribute.String("repo_id", job.repoID.String()),
			attribute.String("maintenance.lane", job.lane.String()),
			attribute.String("maintenance.source", job.source.String()),
			attribute.String("maintenance.level", job.level.String()),
			attribute.Float64("maintenance.debt", job.baseDebt),
		),
	)
	defer span.End()

	wait := time.Since(job.enqueued)
	span.SetAttributes(attribute.Int64("maintenance.queue_wait_ms", wait.Milliseconds()))
	p.metrics.recordWait(ctx, job.lane, wait)

	peeled, discover := p.tips(ctx, job.repoID, job.tips)
	required := dedupeTips(peeled, nil)
	if job.tips != nil && len(required) == 0 {
		// Every push tip peeled to a non-commit; a tip-less pass would
		// bootstrap a bitmap-less flat MIDX. Leave the debt to the scanner.
		span.SetAttributes(attribute.Bool("maintenance.skipped_no_commit_tips", true))
		p.metrics.completed(ctx, job.lane, "skipped")
		return
	}
	span.SetAttributes(attribute.Int("maintenance.tips_required", len(required)))
	discovered := &discoveredTips{discover: discover, required: required}
	start := time.Now()
	err = p.storage.RunMaintenance(ctx, job.repoID, job.level, bitmapfile.Tips{Required: required},
		WithTipDiscoverer(discovered.get))
	dur := time.Since(start)
	p.metrics.recordRun(ctx, job.lane, dur)
	span.SetAttributes(
		attribute.Bool("maintenance.refs_read", discovered.read),
		attribute.Int("maintenance.tips_discovered", len(discovered.tips)),
	)

	switch {
	case err == nil:
		// Best-effort stamp for the classification stats, matching the scanner.
		if rerr := p.storage.RecordMaintenance(job.repoID, time.Now(), dur); rerr != nil {
			slogutil.Warn(ctx, "maintenance pool: record maintenance stamp failed",
				slog.String("repo_id", job.repoID.String()), slog.Any("error", rerr))
		}
		p.metrics.completed(ctx, job.lane, "ok")
	case errors.Is(err, ErrMaintenanceBusy):
		span.SetAttributes(attribute.Bool("maintenance.busy", true))
		p.metrics.completed(ctx, job.lane, "busy")
	case errors.Is(err, ErrRepoNotTracked):
		// A purge untracked the repo after this job was queued.
		span.SetAttributes(attribute.Bool("maintenance.untracked", true))
		p.metrics.completed(ctx, job.lane, "skipped")
	case errors.Is(err, ErrStorageClosing), errors.Is(err, context.Canceled):
		span.SetAttributes(attribute.Bool("maintenance.cancelled", true))
		p.metrics.completed(ctx, job.lane, "cancelled")
	default:
		span.RecordError(err)
		p.metrics.completed(ctx, job.lane, "error")
	}
}

// laneQueue is a max-heap of *maintJob ordered by aging-adjusted priority key.
// All methods use pointer receivers for consistency (recvcheck) — *laneQueue
// still satisfies heap.Interface.

